///////////////////////////////////////////////////////////////////////////////
// FILE:          WidefieldGpuHost.h
// PROJECT:       insiliscope
// SUBSYSTEM:     Simulation engine (no MMDevice dependency)
//-----------------------------------------------------------------------------
// DESCRIPTION:   The WideField GPU host's algorithm, over a backend that runs
//                the kernels of WidefieldGpu.wgsl: Direct3D 11 in the adapter
//                (WidefieldGpuD3D11, HLSL generated by tools/gen_wf_gpu.mjs) or
//                native WebGPU on a Linux server (WidefieldGpuWebGpu,
//                wgpu-native on Vulkan). The viewer's web/wf_gpu.js runs the
//                same steps in the browser; keep the three in step.
//
//                As a WidefieldAccelerator it takes a scene's focus work: plane
//                spectra (resident as fp16 pairs, keyed across jobs), the
//                re-pairing with the kernel spectra, the images. RenderFrames
//                then makes whole stack batches on the GPU: dyes from the
//                images, background, the camera noise chain (the counter-based
//                stream of SMLMCounterRng.h), read back as ADU.
//
//                SelfCheck: a synthetic scene's images against the CPU's
//                (<= 1e-3 rms) and its frame noise (>= 90 % of the pixels
//                equal), so a driver or compiler that gets the kernels wrong
//                leaves the CPU path in charge. One host may be used from any
//                thread (a mutex serializes its calls).
//
// LICENSE:       BSD-3-Clause (see LICENSE at the repository root)

#pragma once

#include "SMLMNoise.h"
#include "WidefieldRender.h"

#include <cstdint>
#include <memory>
#include <mutex>
#include <string>
#include <vector>

namespace sim {

// What the host needs of a GPU API: raw storage buffers of 32-bit words, the kernels by name (a 64-byte block of
// parameters at binding 0, the buffers at bindings 1.. in order), copies, read-back. Work runs in the order asked.
class GpuBackend
{
public:
   struct Buffer
   {
      virtual ~Buffer() = default;
      size_t bytes = 0;
   };
   using BufPtr = std::shared_ptr<Buffer>;

   virtual ~GpuBackend() = default;
   // A buffer of at least bytes (rounded up to 4), holding data if given (else zeros); nullptr (err) if it cannot be
   // made (too large for one binding: MaxBinding).
   virtual BufPtr Make(size_t bytes, const void* data, std::string& err) = 0;
   virtual bool Write(Buffer& b, size_t offset, const void* data, size_t bytes, std::string& err) = 0;
   virtual bool Copy(Buffer& dst, Buffer& src, size_t bytes, std::string& err) = 0;
   virtual bool Dispatch(const char* kernel, const uint32_t* params, size_t nParams, Buffer* const* bufs, size_t nBufs,
                         unsigned x, unsigned y, unsigned z, std::string& err) = 0;
   virtual bool ReadBack(Buffer& src, size_t bytes, void* dst, std::string& err) = 0;
   // The largest buffer one binding takes.
   virtual size_t MaxBinding() const { return ~size_t(0); }
   // The resident plane pool's sizes to try, largest first (MB; each also at most MaxBinding), and how many scenes'
   // planes the host keeps (beyond them the least recently used are dropped). 16 or more: a structured pattern's
   // state scenes go to the GPU too (WidefieldAccelerator::ManyScenes).
   virtual std::vector<size_t> PoolMB() const { return {512, 128}; }
   virtual size_t MaxScenes() const { return 4; }
};

class WidefieldGpuHost : public WidefieldAccelerator
{
public:
   explicit WidefieldGpuHost(std::unique_ptr<GpuBackend> backend);
   ~WidefieldGpuHost() override;

   bool HasPlane(unsigned long long geometry, unsigned long long key) const override;
   bool Images(const WidefieldGpuJob& job, std::vector<std::vector<float>>& out, std::string& err) override;
   bool Fits(unsigned long long geometry, unsigned NX, unsigned NY, size_t planes) override;
   bool ManyScenes() const override { return backend_->MaxScenes() >= 16; }

   // Per-pixel frame inputs (width x height; empty maps = the scalar from
   // cam): offset ADU, gain photons/ADU, read noise e-, background photons
   // before the per-frame fade (empty = flatBg).
   bool SetFrameStatic(unsigned width, unsigned height, const std::vector<float>& offset,
                       const std::vector<float>& gain, const std::vector<float>& readNoise,
                       const std::vector<float>& background, double flatBg, const CameraNoiseParams& cam,
                       std::string& err);
   // Frames k = 0..n-1: images (the scene's, for its focus) with bleach
   // coefficients coef[k], background x bgScale[k], noise keyed by
   // (seed, frames[k]); outs[k] receives width x height ADU.
   bool RenderFrames(const WidefieldImages& images, const std::vector<std::vector<double>>& coef,
                     const std::vector<uint32_t>& frames, const std::vector<double>& bgScale,
                     const CameraNoiseParams& cam, uint32_t seed, const std::vector<std::vector<uint16_t>*>& outs,
                     std::string& err);

   // The synthetic scene against the CPU (see the file comment); err says how it failed.
   bool SelfCheck(std::string& err);

   GpuBackend& Backend() { return *backend_; }

private:
   bool ImagesImpl(const WidefieldGpuJob& job, std::vector<std::vector<float>>& out, std::string& err);
   struct State;
   std::unique_ptr<GpuBackend> backend_;
   std::unique_ptr<State> s_;
   mutable std::recursive_mutex mu_;
};

} // namespace sim
